// src/components/comparison/topo003-qa-fixtures.ts  (dev/QA only, never imported by Comparison)
//
// NWP-TOPO-003 QA scenarios for the ComparisonDev page.
//
// Turns each topology fixture in topology/qa-fixtures.ts (generated by
// ENGINE-016's buildTopology) into a VendorPlansPayload, so every fixture
// appears as its own scenario button. Each scenario has one TP-Link Omada
// Cost-Efficient plan; the High-Performance panel stays empty, as in the
// existing `nullPrice` scenario.
//
// BOM lines are built from the fixture: quantities are read from the
// topology nodes, and the lifecycle status follows the node status, so the
// BOM table and the canvas agree. Unit prices are representative dev values
// only, in the same spirit as the other fixtures in fixtures.ts.

import { TOPOLOGY_QA_FIXTURES } from "@/components/topology/qa-fixtures";
import type { TopologyNode } from "@/components/topology/types";
import type {
  BomCategory,
  BomLineItem,
  NetworkPlanData,
  VendorPlansPayload,
} from "./types";

const AT = "Nov 17, 2026, 9:00 AM";
const VENDOR = "TP-Link Omada" as const;
const TIER = "Cost-Efficient" as const;

/** Representative PHP unit prices for the fixture SKUs (dev data only). */
const UNIT_PRICE: Record<string, number> = {
  ER7206: 9800,
  ER8411: 26500,
  ER7212PC: 14500,
  OC200: 4800,
  SG3428: 9500,
  SG3428MP: 21000,
  SG2428P: 15500,
  SX3008F: 18000,
  EAP610: 5200,
  EAP670: 8900,
};

const BOM_CATEGORIES: readonly BomCategory[] = [
  "Gateway",
  "Switch",
  "Access Point",
  "Optic",
  "Enclosure",
  "Controller",
  "Installation Material",
];

function toBomCategory(value: string, sku: string): BomCategory {
  const match = BOM_CATEGORIES.find((category) => category === value);
  if (!match) {
    throw new Error(`TOPO-003 QA fixture: unknown BOM category "${value}" for ${sku}.`);
  }
  return match;
}

/**
 * Quantity of a SKU, read from the topology. Switches have one node per unit,
 * so they are counted. Other devices carry `qty` on their node. The firewall
 * node shares the gateway SKU and is skipped.
 */
function quantityFor(sku: string, nodes: TopologyNode[]): number {
  const deviceNodes = nodes.filter((node) => node.sku === sku && node.role !== "firewall");
  const switchUnits = deviceNodes.filter((node) => node.role === "switch").length;
  if (switchUnits > 0) return switchUnits;
  return deviceNodes.find((node) => typeof node.qty === "number")?.qty ?? 1;
}

function statusFor(sku: string, nodes: TopologyNode[]): BomLineItem["status"] {
  return nodes.find((node) => node.sku === sku && node.status)?.status ?? "ACTIVE";
}

function toPlan(name: string): NetworkPlanData {
  const fixture = TOPOLOGY_QA_FIXTURES[name];
  const nodes = fixture.plan.topology?.nodes ?? [];

  const bom: BomLineItem[] = fixture.plan.bom.map((line) => {
    const quantity = quantityFor(line.sku, nodes);
    const unitPrice = UNIT_PRICE[line.sku] ?? null;
    return {
      sku: line.sku,
      name: line.name,
      category: toBomCategory(line.category, line.sku),
      quantity,
      unitPrice,
      subtotal: unitPrice === null ? null : unitPrice * quantity,
      status: statusFor(line.sku, nodes),
      priceSource: "synchronized",
      isStale: false,
      priceUpdatedAt: "2026-11-16",
      isGeneric: false,
    };
  });

  return {
    vendor: VENDOR,
    tier: TIER,
    bom,
    topology: fixture.plan.topology ?? null,
    generatedAt: AT,
    currency: "PHP",
    totalCost: bom.reduce((sum, line) => sum + (line.subtotal ?? 0), 0),
    totalIsPartial: bom.some((line) => line.unitPrice === null),
    complete: true,
    unmet: [],
    // Shown wherever the plan card lists advisories, so QA can see what the
    // scenario is for without opening this file.
    advisories: [
      `TOPO-003 QA fixture: ${fixture.description}`,
      `Covers: ${fixture.tests.join("; ")}`,
    ],
  };
}

/** One scenario per fixture, keyed `topo003:<fixtureName>`. */
export const topo003QaScenarios: Record<string, VendorPlansPayload> =
  Object.fromEntries(
    Object.keys(TOPOLOGY_QA_FIXTURES).map((name) => [
      `topo003:${name}`,
      { [VENDOR]: { [TIER]: toPlan(name) } },
    ]),
  );